  function get_total_carrito(){
	var total = 0;
	for(var elemento of carrito){
		total += parseInt(elemento.total);
	}
	return total;
  }




$(document).on('click', '.btnFinalizar', async function(e) {
	var csrf_token = $('meta[name="csrf-token"]').attr('content');

	var data = {
		carrito: carrito,
		_token: csrf_token,
		total:get_total_carrito()
	};

	// Envía la solicitud AJAX
	$.ajax({
		url: '/devoluciones-simples', // Cambia esta URL a la ruta correcta en tu aplicación
		type: 'POST',
		data: data,
		success: function(response) {
			sessionStorage.removeItem('carrito');
			toastr.success('Devoluciones guardadas  correctamente','Mensaje');
			setTimeout(()=>{
				location.reload();
			},1000)
		},
		error: function(error) {
			// Maneja los errores
			console.error('Error al guardar', error);
		}
	});
});

  



  function getProductoById(id){
    return new Promise((resolve, reject)=>{
        $.ajax({
            url:`/productos/${id}`,
            method:'get',
            success:function(response){
               resolve(response);
            }
        });
    })
}



function getProducto(sku){
    return new Promise((resolve, reject)=>{
        $.ajax({
            url:`/productos/sku/${sku}`,
            method:'get',
            success:function(response){
               resolve(response);
            }
        });
    })
}

