function getMesesPlan(nombre){
	var data = {
		nombre:nombre
	};
	$.ajax({
		url:url+'/getMesesPlan',
		method:'post',
		data:data,
		headers: {
	        'X-CSRF-TOKEN': $('meta[name="csrf-token"]').attr('content')
	    },
		success:function(info){
			htmlOptions = `<option value="">Seleccione tiempo</option>`;
			$.each(info.mesesPlan, function(element){
				htmlOptions+=`
					<option value="${this.id}"> ${this.tiempo_meses} Meses </option>
				`;
			});
			$('#tiempo').html(htmlOptions);
		}
	})
}


