function crearFactura(){
	var nombres = $('input[name=nombres]').val();
	var documento = $('input[name=documento]').val();
	var email = $('input[name=email]').val();
	var password = $('input[name=password]').val();

	if(nombres=='' || documento=='' || email =='' || password==''){
		show_error('Todos los campos son obligatorios.');
		return false;
	}

	if(carrito.length==0){
		show_error('Agrege una compra al carrito.');
		return false;
	}


	var user = {
		nombres:nombres,
		documento:documento,
		email:email,
		password:password
	};

	$.ajax({
		url:url+'/crearFactura',
		method:'post',
		data:{carrito:carrito, total:setTotalCarrito(), user:user},
		headers: {
	        'X-CSRF-TOKEN': $('meta[name="csrf-token"]').attr('content')
	    },
		success:function(info){
			open_checkout(info);
		}
	});
}


function open_checkout(dataPago) {
			$("html, body").animate({
				scrollTop: 0
			}, 0);

			var checkout = new WidgetCheckout({
				currency: 'COP',
				amountInCents: dataPago.total + '00',
				reference: dataPago.reference,
				publicKey: dataPago.public_key,
				//publicKey:'pub_test_01onJEFsoghGOjCnXF1l7IFcGIFgcha6',
				redirectUrl: dataPago.WOMPI_REDIRECT_URL+'/respuesta'
			});

			checkout.open(function(result) {
				var transaction = result.transaction
			    location.href = url+'/respuesta?id='+transaction.id;

			});
}


function formatNumber(num){
	
	let options = {
	  style: "decimal",
	  minimumFractionDigits: 0,
	  maximumFractionDigits: 0,
	  useGrouping: true,
	  currency: "COP"
	};
	return num.toLocaleString("en-US", options);
}

function eliminar_carrito(){
	sessionStorage.removeItem('carrito');
}

